#[inline]
fn destack_input_clipboard_list_items_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeSlice<ClipboardItemDescriptor>,
) -> RuntimeResult<()> {
    binding.trace().run_binding_without_context(
        INPUT_CLIPBOARD_LIST_ITEMS,
        binding.replay_payload_for(INPUT_CLIPBOARD_LIST_ITEMS)?,
        || match world {
            RuntimeWorld::Host => unsafe { platform_native::destack_input_clipboard_list_items(binding, out) },
            RuntimeWorld::Simulation => unsafe { platform_simulation_native::destack_input_clipboard_list_items(binding, out) },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeSlice<ClipboardItemDescriptor> = unsafe { out.read() };
                let result_recorded_slice = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_slice.len());
                for result_recorded_item in result_recorded_slice.iter().cloned() {
                    let result_recorded_item_recorded_presentation_style = result_recorded_item.presentation_style;
                    let result_recorded_item_recorded_representations_slice = unsafe { result_recorded_item.representations.as_slice()? };
                    let mut result_recorded_item_recorded_representations = Vec::with_capacity(result_recorded_item_recorded_representations_slice.len());
                    for result_recorded_item_recorded_representations_item in result_recorded_item_recorded_representations_slice.iter().cloned() {
                        let result_recorded_item_recorded_representations_item_recorded_mime_type = unsafe { result_recorded_item_recorded_representations_item.mime_type.as_str()? }.to_string();
                        let result_recorded_item_recorded_representations_item_recorded_kind = result_recorded_item_recorded_representations_item.kind;
                        let result_recorded_item_recorded_representations_item_recorded_name = if let Some(value) = result_recorded_item_recorded_representations_item.name {
                            let result_recorded_item_recorded_representations_item_recorded_name_inner = unsafe { value.as_str()? }.to_string();
                            Some(result_recorded_item_recorded_representations_item_recorded_name_inner)
                        } else {
                            None
                        };
                        let result_recorded_item_recorded_representations_item_recorded_is_directory = result_recorded_item_recorded_representations_item.is_directory;
                        let result_recorded_item_recorded_representations_item_recorded_byte_length = if let Some(value) = result_recorded_item_recorded_representations_item.byte_length {
                            let result_recorded_item_recorded_representations_item_recorded_byte_length_inner = value;
                            Some(result_recorded_item_recorded_representations_item_recorded_byte_length_inner)
                        } else {
                            None
                        };
                        let result_recorded_item_recorded_representations_item_recorded = ClipboarditemrepresentationdescriptorReplayRecord {
                            mime_type: result_recorded_item_recorded_representations_item_recorded_mime_type,
                            kind: result_recorded_item_recorded_representations_item_recorded_kind,
                            name: result_recorded_item_recorded_representations_item_recorded_name,
                            is_directory: result_recorded_item_recorded_representations_item_recorded_is_directory,
                            byte_length: result_recorded_item_recorded_representations_item_recorded_byte_length,
                        };
                        result_recorded_item_recorded_representations.push(result_recorded_item_recorded_representations_item_recorded);
                    }
                    let result_recorded_item_recorded = ClipboarditemdescriptorReplayRecord {
                        presentation_style: result_recorded_item_recorded_presentation_style,
                        representations: result_recorded_item_recorded_representations,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = InputClipboardListItemsReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputClipboardListItemsReplayRecord {
                        result,
                    }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native = binding.store_slice_with(value.len(), |value_native_values| {
                        for value_native_item in value {
                            let value_native_decoded_presentation_style = value_native_item.presentation_style;
                            let value_native_decoded_representations = binding.store_slice_with(value_native_item.representations.len(), |value_native_decoded_representations_values| {
                                for value_native_decoded_representations_item in value_native_item.representations {
                                    let value_native_decoded_representations_decoded_mime_type = binding.store_string_owned(value_native_decoded_representations_item.mime_type);
                                    let value_native_decoded_representations_decoded_kind = value_native_decoded_representations_item.kind;
                                    let value_native_decoded_representations_decoded_name = if let Some(value) = value_native_decoded_representations_item.name {
                                        let value_native_decoded_representations_decoded_name_inner = binding.store_string_owned(value);
                                        Some(value_native_decoded_representations_decoded_name_inner)
                                    } else {
                                        None
                                    };
                                    let value_native_decoded_representations_decoded_is_directory = value_native_decoded_representations_item.is_directory;
                                    let value_native_decoded_representations_decoded_byte_length = if let Some(value) = value_native_decoded_representations_item.byte_length {
                                        let value_native_decoded_representations_decoded_byte_length_inner = value;
                                        Some(value_native_decoded_representations_decoded_byte_length_inner)
                                    } else {
                                        None
                                    };
                                    let value_native_decoded_representations_decoded = ClipboardItemRepresentationDescriptor {
                                        mime_type: value_native_decoded_representations_decoded_mime_type,
                                        kind: value_native_decoded_representations_decoded_kind,
                                        name: value_native_decoded_representations_decoded_name,
                                        is_directory: value_native_decoded_representations_decoded_is_directory,
                                        byte_length: value_native_decoded_representations_decoded_byte_length,
                                    };
                                    value_native_decoded_representations_values.push(value_native_decoded_representations_decoded);
                                }
                                Ok(())
                            })?;
                            let value_native_decoded = ClipboardItemDescriptor {
                                presentation_style: value_native_decoded_presentation_style,
                                representations: value_native_decoded_representations,
                            };
                            value_native_values.push(value_native_decoded);
                        }
                        Ok(())
                    })?;
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

