#[inline]
fn destack_input_device_close_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    handle: resource::InputDeviceHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.trace().run_binding_without_context(
        INPUT_DEVICE_CLOSE,
        binding.replay_payload_for(INPUT_DEVICE_CLOSE)?,
        || match world {
            RuntimeWorld::Host => unsafe { platform_native::destack_input_close(binding, handle) },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_input_close(binding, handle)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = InputDeviceCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputDeviceCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

