#[inline]
fn destack_input_gamepad_set_light_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    handle: resource::InputDeviceHandle,
    red: u8,
    green: u8,
    blue: u8,
) -> RuntimeResult<()> {
    let _ = (&handle, &red, &green, &blue);

    binding.trace().run_binding_without_context(
        INPUT_GAMEPAD_SET_LIGHT,
        binding.replay_payload_for(INPUT_GAMEPAD_SET_LIGHT)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_input_gamepad_set_light(binding, handle, red, green, blue)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_input_gamepad_set_light(
                    binding, handle, red, green, blue,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = InputGamepadSetLightReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputGamepadSetLightReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

