#[inline]
fn destack_input_pointer_capture_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    handle: resource::InputDeviceHandle,
    target: InputWindowTarget,
    enabled: bool,
) -> RuntimeResult<()> {
    let _ = (&handle, &target, &enabled);

    binding.trace().run_binding_without_context(
        INPUT_POINTER_CAPTURE,
        binding.replay_payload_for(INPUT_POINTER_CAPTURE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_input_pointer_capture(binding, handle, target, enabled)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_input_pointer_capture(
                    binding, handle, target, enabled,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = InputPointerCaptureReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputPointerCaptureReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

