fn destack_input_rawhid_get_feature_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeSlice<u8>,
    handle: resource::InputDeviceHandle,
    reportid: u8,
    maxbytes: u32,
) -> RuntimeResult<()> {
    let _ = (&handle, &reportid, &maxbytes);

    binding.trace().run_binding_without_context(
        INPUT_RAWHID_GET_FEATURE,
        binding.replay_payload_for(INPUT_RAWHID_GET_FEATURE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_input_raw_hid_get_feature(
                    binding, out, handle, reportid, maxbytes,
                )
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_input_raw_hid_get_feature(
                    binding, out, handle, reportid, maxbytes,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeSlice<u8> = unsafe { out.read() };
                let result_recorded_slice = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_slice.len());
                for result_recorded_item in result_recorded_slice.iter().cloned() {
                    let result_recorded_item_recorded = result_recorded_item;
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = InputRawhidGetFeatureReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputRawhidGetFeatureReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native =
                        binding.store_slice_with(value.len(), |value_native_values| {
                            for value_native_item in value {
                                let value_native_decoded = value_native_item;
                                value_native_values.push(value_native_decoded);
                            }
                            Ok(())
                        })?;
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

