#[inline]
fn destack_input_device_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    handle: resource::InputDeviceHandle,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        INPUT_DEVICE_CLOSE,
        binding.replay_payload_for(INPUT_DEVICE_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_input_close(binding, context, handle),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_input_close(binding, context, handle)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = InputDeviceCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputDeviceCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_input_device_close_result(context, result)?;
    Ok(result)
}

