#[inline]
fn destack_input_pointer_capture_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    handle: resource::InputDeviceHandle,
    target: InputWindowTargetVm,
    enabled: bool,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        INPUT_POINTER_CAPTURE,
        binding.replay_payload_for(INPUT_POINTER_CAPTURE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_input_pointer_capture(
                binding, context, handle, target, enabled,
            ),
            RuntimeWorld::Simulation => platform_simulation_vm::destack_input_pointer_capture(
                binding, context, handle, target, enabled,
            ),
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = InputPointerCaptureReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputPointerCaptureReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_input_pointer_capture_result(context, result)?;
    Ok(result)
}

